package uz.plugin.audio_player

/**
 * The API Dart calls through JNI (bindings in `lib/src/bindings/audio_player_api.g.dart`, generated by
 * `dart run tool/jnigen.dart` from the compiled classes). It takes only ids, `String`s and callback interfaces, and
 * forwards every call to the calling engine's [AudioPlayerHost].
 *
 * Requests and replies are the JSON form of the platform interface messages, with the same method names and fields
 * the former method channel used. Results come back through [ResultCallback], playback events through
 * [PlaybackListener]. A call whose engine is not attached fails with the code `detached`; so does one
 * without an engine id while several engines are attached, so a call never lands in another engine.
 */
object AudioPlayerApi {

    /**
     * Answers calls: [onResult] with the JSON reply, or [onError], each with the `callId` the call was made with.
     * Dart keeps one per isolate for all its calls.
     */
    interface ResultCallback {
        fun onResult(callId: Long, json: String?)

        fun onError(callId: Long, code: String?, message: String?, details: String?)
    }

    /** Events of every player of one isolate; `playerId` says which one. */
    interface PlaybackListener {
        /** A playback event (JSON of `PlaybackEventMessage`). */
        fun onPlaybackEvent(playerId: String?, json: String?)

        /** A data update (JSON of `PlayerDataMessage`). */
        fun onPlayerData(playerId: String?, json: String?)

        /** An error reported on the playback event stream; the next playback event carries it as well. */
        fun onPlaybackError(playerId: String?, code: String?, message: String?, details: String?)
    }

    /**
     * Sets the listener [listenerId] of engine [engineId] (`PlatformDispatcher.instance.engineId`, 0 when Dart has
     * none). A player's events go only to the listener of the isolate that created it (`listenerId` of `init`).
     * A non-zero [engineId] comes from the engine's root isolate: a new root listener means a hot restart, which
     * releases every player and listener the engine had.
     */
    @JvmStatic
    fun setPlaybackListener(engineId: Long, listenerId: String, listener: PlaybackListener?) {
        AudioPlayerHost.forEngine(engineId)?.setListener(engineId != AudioPlayerHost.NO_ENGINE, listenerId, listener)
    }

    /** Calls a plugin-level method of engine [engineId]: `init`, `disposePlayer` or `disposeAllPlayers`. */
    @JvmStatic
    fun call(engineId: Long, callId: Long, method: String, request: String?, callback: ResultCallback) {
        val host = AudioPlayerHost.forEngine(engineId)
        if (host == null) detached(callId, callback) else host.call(method, request, CallbackResult(callback, callId))
    }

    /** Calls a method of the player [playerId] of engine [engineId]. */
    @JvmStatic
    fun callPlayer(
        engineId: Long,
        callId: Long,
        playerId: String,
        method: String,
        request: String?,
        callback: ResultCallback,
    ) {
        val host = AudioPlayerHost.forEngine(engineId)
        if (host == null) {
            detached(callId, callback)
        } else {
            host.callPlayer(playerId, method, request, CallbackResult(callback, callId))
        }
    }

    private fun detached(callId: Long, callback: ResultCallback) {
        callback.onError(callId, ErrorCode.DETACHED, "No Flutter engine is attached", null)
    }
}
